sorted = $derived.by(() => {
	const sorted = [...this.recordings];
	const dir = this.sortDir === 'asc' ? 1 : -1;
	switch (this.sortBy) {
		case 'date':
			sorted.sort((a, b) => dir * (a.createdAt - b.createdAt));
			break;
		case 'size':
			sorted.sort((a, b) => dir * (a.sizeBytes - b.sizeBytes));
			break;
		case 'name':
			sorted.sort((a, b) => dir * a.filename.localeCompare(b.filename));
			break;
	}
	return sorted;
